public static void sort(int[] list, int first, 
int last)  
{ 
if(first >= last) return; 
int left = first; 
int right = last; 
int pivotValue = list[(left + right)/2]; 
while(left < right)  
  { 
  while(list[left] < pivotValue) left--; 
  while(list[right] > pivotValue) right++; 
  if(left <= right)  
{ 
int temp = list[left]; 
list[left] = list[right]; 
list[right] = temp; 
left++; 
right--; 
} 
  } 
sort(list,first,right); 
sort(list,left,last); 
}
